```js
const { run, loading } = useRequest(toRealName, {
  manual: true,
  onSuccess: async () => {
    refresh();
    uni.navigateBack({
      delta: 1,
    });
  },
});
useShowLoading(loading, { title: "正在提交中..." });
```

