## 前置知识点

### WeakMap

`WeakMap` 是 ES6 新加入的数据结构，它与 `map` 类似，但是键为弱引用。

> 弱引用就是指不计入垃圾回收次数，当引用被垃圾回收 `WeakMap` 对应键值自动消失。

> 更多内容请参考[文档](https://developer.mozilla.org/zh-CN/docs/Web/JavaScript/Reference/Global_Objects/WeakMap)

### WeakSet

与 `WeakMap` 类似，不同在于 `WeakSet` 只有键名，没有键值。

> 更多内容请参考[文档](https://developer.mozilla.org/zh-CN/docs/Web/JavaScript/Reference/Global_Objects/WeakSet)

### Class 私有属性

之前 `Class` 要实现私有属性只能通过，`Symbol` 或者外部变量来实现，不过都各有缺点，现在新的提案 [proposal-private-methods](https://github.com/tc39/proposal-private-methods) 添加了私有属性和私有方法，使用方式很简单，直接`#<name>`即可。

```js
class Test {
  #age = 12;
  #getage() {}
}
```

私有属性只能在构造函数内部调用，如果在非内部调用则抛出异常（在 static 上调用也是可以的）。

## 示例文件

```js
class Test {
  #age = 17;
  static #name = 'zhangsan';

  #getAge() {
    console.log(this.#age);
  }
  static #getName() {
    console.log(this.#name);
  }

  all() {
    this.#getAge();
    Test.#getName();
  }
}
const test = new Test();
test.all();
```

以下内容根据此文件进行讲解。

## babel

```js
'use strict';

function _classCallCheck(instance, Constructor) {
  if (!(instance instanceof Constructor)) {
    throw new TypeError('Cannot call a class as a function');
  }
}

function _defineProperties(target, props) {
  for (var i = 0; i < props.length; i++) {
    var descriptor = props[i];
    descriptor.enumerable = descriptor.enumerable || false;
    descriptor.configurable = true;
    if ('value' in descriptor) descriptor.writable = true;
    Object.defineProperty(target, descriptor.key, descriptor);
  }
}

function _createClass(Constructor, protoProps, staticProps) {
  if (protoProps) _defineProperties(Constructor.prototype, protoProps);
  if (staticProps) _defineProperties(Constructor, staticProps);
  Object.defineProperty(Constructor, 'prototype', { writable: false });
  return Constructor;
}

function _classPrivateMethodInitSpec(obj, privateSet) {
  _checkPrivateRedeclaration(obj, privateSet);
  privateSet.add(obj);
}

function _classPrivateFieldInitSpec(obj, privateMap, value) {
  _checkPrivateRedeclaration(obj, privateMap);
  privateMap.set(obj, value);
}

function _checkPrivateRedeclaration(obj, privateCollection) {
  if (privateCollection.has(obj)) {
    throw new TypeError(
      'Cannot initialize the same private elements twice on an object'
    );
  }
}

function _classStaticPrivateMethodGet(receiver, classConstructor, method) {
  _classCheckPrivateStaticAccess(receiver, classConstructor);
  return method;
}

function _classPrivateMethodGet(receiver, privateSet, fn) {
  if (!privateSet.has(receiver)) {
    throw new TypeError('attempted to get private field on non-instance');
  }
  return fn;
}

function _classStaticPrivateFieldSpecGet(
  receiver,
  classConstructor,
  descriptor
) {
  _classCheckPrivateStaticAccess(receiver, classConstructor);
  _classCheckPrivateStaticFieldDescriptor(descriptor, 'get');
  return _classApplyDescriptorGet(receiver, descriptor);
}

function _classCheckPrivateStaticFieldDescriptor(descriptor, action) {
  if (descriptor === undefined) {
    throw new TypeError(
      'attempted to ' + action + ' private static field before its declaration'
    );
  }
}

function _classCheckPrivateStaticAccess(receiver, classConstructor) {
  if (receiver !== classConstructor) {
    throw new TypeError('Private static access of wrong provenance');
  }
}

function _classPrivateFieldGet(receiver, privateMap) {
  var descriptor = _classExtractFieldDescriptor(receiver, privateMap, 'get');
  return _classApplyDescriptorGet(receiver, descriptor);
}

function _classExtractFieldDescriptor(receiver, privateMap, action) {
  if (!privateMap.has(receiver)) {
    throw new TypeError(
      'attempted to ' + action + ' private field on non-instance'
    );
  }
  return privateMap.get(receiver);
}

function _classApplyDescriptorGet(receiver, descriptor) {
  if (descriptor.get) {
    return descriptor.get.call(receiver);
  }
  return descriptor.value;
}

var _age = /*#__PURE__*/ new WeakMap();

var _getAge = /*#__PURE__*/ new WeakSet();

var Test = /*#__PURE__*/ (function () {
  debugger;
  function Test() {
    _classCallCheck(this, Test);

    _classPrivateMethodInitSpec(this, _getAge);

    _classPrivateFieldInitSpec(this, _age, {
      writable: true,
      value: 17,
