  color: red;
}
a,
a,
a,
a,
a,
a,
a,
a,
a,
a,
a,
a,
a,
a,
a,
a,
a,
a {
  color: #666;
}
```

输出结果还是红色。

## 增加优先级

传统添加优先级我们可能会通过给标签添加 id 或者继续嵌套来实现，不过这样做肯定不合适因为后面在想修改可能就需要使用`style`或者`important`了，下面就说下两个小技巧

1. 使用属性选择器

```css
.a[class] {
  color: red;
}
.a {
  color: #666;
}
```

2. 嵌套选择自己

```css
.a.a {
  color: red;
}
.a {
  color: #666;
}
```

## 匹配顺序

说一点新手噩梦，css 的匹配顺序是从右往左，所以嵌套太多层的 css 语句就不要在写了，一般而言 id 选择器和类选择器的解析最快，标签选择器的速度很慢，所以在项目中不要嵌入太多的标签选择器有利于项目的优化。

## 是否区分大小写

说这个首先要说一下 html 是否区分大小写，html 对于标签和属性是不区分大小写的，而对属性值则是区分的，css 与 html 保持一致

```html
<style>
  p {
    color: #666;
  }
  [CLASS] {
    color: red;
  }
  .foo {
    color: white;
  }
</style>
<p class="FOO">hello wrold</p>
```

这里 p 的 `color` 为 `red`，说明了标签和属性选择器不区分大小写，而对于 class 则是区分的。

> new 运算符创建一个用户定义的对象类型的实例或具有构造函数的内置对象的实例。

上面的定义有点抽象，我们来通过一个例子看 new 运算符扮演的角色

```js
function Foo(name, age) {
  this.name = name;
  this.age = age;
}
Foo.prototype.getName = function() {
  return this.name;
};
Foo.prototype.foo = "foo";
var f = new Foo("zhangsan", 18);
f.getName(); // zhangsan
f.foo; // foo
```

上面通过 new 创建了一个新的对象，并且这个对象通过原型链访问到了原型上的方法和属性，所以 new 运算符就是执行构造函数返回一个实例对象。

new 运算符在执行时执行了下面四步：

1. 创建一个空的简单 JavaScript 对象（即{}）；
2. 链接该对象（即设置该对象的构造函数）到另一个对象 ；
3. 将步骤 1 新创建的对象作为 this 的上下文 ；
4. 如果该函数没有返回对象，则返回 this。

## 实现

根据上面的执行步骤我们来尝试实现下，当然 new 操作符肯定是模拟不了了，下面通过函数的形式展示

```js
function newCall(fn) {
  var args = Array.prototype.slice.call(arguments, 1);
  var obj = {};
  obj.__proto__ = fn.prototype;
  var result = fn.apply(obj, args);
  return result && typeof result === "object" ? result : obj;
}
```

Ok，到这里就实现了一个模拟 new 的操作，我们测试一下

```js
function Otaku(name, age) {
  this.name = name;
  this.age = age;

  this.habit = "Games";
}

Otaku.prototype.strength = 60;

Otaku.prototype.sayYourName = function() {
  console.log("I am " + this.name);
};

function newCall(fn) {
  var args = Array.prototype.slice.call(arguments, 1);
  var obj = {};
  obj.__proto__ = fn.prototype;
  var result = fn.apply(obj, args);
  return result && typeof result === "object" ? result : obj;
}

var person = newCall(Otaku, "Kevin", "18");

console.log(person.name); // Kevin
console.log(person.habit); // Games
console.log(person.strength); // 60
```

撒花 ✿✿ ヽ(°▽°)ノ ✿，不过额外提醒一下`__proto__`是浏览器实现的非标准属性，一般情况下不推荐使用，不过既然是模拟 es5 推荐的`Object.setPrototypeOf`肯定没办法用了，只能将就着用了

之前说了[模拟实现 call 和 apply](https://github.com/bosens-China/blog/issues/30)，下面就来实现 bind，首先先看一下定义 bind 定义

> bind()方法创建一个新的函数，在 bind()被调用时，这个新函数的 this 被 bind 的第一个参数指定，其余的参数将作为新函数的参数供调用时使用。

## 第一版

根据定义我们尝试写一下

```js
Function.prototype.binds = function(con) {
  var fn = this;
  var args = Array.prototype.slice.call(arguments, 1);
  return function() {
    return fn.apply(con, args);
  };
};
```

我们来测试一下上面的函数

```js
var obj = {
  value: "zhangsan"
};
function foo(name, age) {
  console.log(this.value); //zhangsan
  console.log(name); // name
  console.log(age); // undefined
}
var f = foo.binds(obj, "name");
f(19);
```

`age` 输出的跟我们预期的不太一致，这是因为我们没有处理返回函数的参数，用 concat 把参数合并在一起就可以了。

```js
Function.prototype.binds = function(con) {
  var fn = this;
  var args = Array.prototype.slice.call(arguments, 1);
  return function() {
    return fn.apply(con, args.concat(Array.prototype.slice.call(arguments)));
  };
};
```

## 第二版

上面简单实现了函数的 bind，不过我们来看一下 bind 与构造函数相遇会怎么样

```js
var obj = {
  value: "zhangsan"
};
function Foo(name, age) {
  console.log(this.value); //undefined
  console.log(name);
  console.log(age);
}
var f = Foo.bind(obj, "name");
new f(19);
```

上面 `this.value` 的输出为 `undefined`，这是因为 **调用绑定函数时作为 this 参数传递给目标函数的值。 如果使用 new 运算符构造绑定函数，则忽略该值**。

另外作为构造函数是可以获取到绑定 bind 函数的 `prototype` 的

```js
function Foo() {
  console.log(this.gender); //male
}
Foo.prototype.gender = "male";
var f = Foo.bind(null, "name");
new f();
```

下面就是来实现上面两点：

- 怎么来判断是否通过 new 来调用呢？可以通过`instanceof`

```js
function Foo() {
  if (!(this instanceof Foo)) {
    throw Error("请通过new调用");
  }
}
Foo();
```

- 继承的话我们可以通过寄生组合式继承，这类文章比较多，这里就简单举一个例子

```js
function create(con) {
  var f = function() {};
  f.prototype = con;
  return new f();
}
function Par(name) {
  this.name = name;
}
Par.prototype.getName = function() {
  return this.name;
};
function Chi(name, age) {
  Par.call(this, name);
  this.age = age;
}
Chi.prototype = create(Par.prototype);
Chi.prototype.constructor = Chi;
Chi.prototype.getDetails = function() {
  var n = this.getName();
  console.log(n, this.age);
};
var d = new Chi("zhangsan", 16);
d.getDetails();
```

OK，上面两点解决后我们再来实现一版

```js
Function.prototype.binds = function(con) {
  var fn = this;
  var args = Array.prototype.slice.call(arguments, 1);
  var f = function() {};
  if (this.prototype) {
    f.prototype = this.prototype;
  }
  var result = function() {
    return fn.apply(
      this instanceof result ? this : con,
      args.concat(Array.prototype.slice.call(arguments))
    );
  };
  result.prototype = new f();
  return result;
};
```

## 优化

观察上面的不难发现 bind 调用的必须是函数，而通过继承我们可能会调用到 bind 所以这里显示报错一下

```js
var obj = Object.create(Function.prototype);
console.log(obj.bind);
```

另外对于我们上面定义的`binds`肯定不太优雅，污染了命名空间，这里可以判断一下如果存在 `bind` 就用 `bind` 否则在定义

## 最终

```js
if (!Function.prototype.bind) {
  Function.prototype.bind = function(con) {
    if (typeof this !== "function") {
      throw new TypeError(
        "Function.prototype.bind - what is trying to be bound is not callable"
      );
    }
    var fn = this;
    var args = Array.prototype.slice.call(arguments, 1);
    var f = function() {};
    if (this.prototype) {
      f.prototype = this.prototype;
    }
    var result = function() {
      return fn.apply(
        this instanceof result ? this : con,
        args.concat(Array.prototype.slice.call(arguments))
      );
    };
    result.prototype = new f();
    return result;
  };
}
```

> call() 方法使用一个指定的 this 值和单独给出的一个或多个参数来调用一个函数

上面是 call 的定义，apply 与 call 类似只是第二个参数是一个数组而 call 接收的则是一个参数列表。

看一个例子

```js
var obj = {
  name: "obj"
};
function foo() {
  return this.name;
}
foo.call(obj); //obj
```

上面通过 call 改变了 this 的指向，下面就是模拟实现

## 实现

call 和 apply 是 es5 的方法，既然是模拟实现那肯定不能用 es5 方法了，我们先分析一下怎么来指定 this，this 跟动态作用域类似是在执行时确定，那我们在指定 this 的属性上添加一个方法并且执行，那么这个方法的 this 就是指定 this

```js
var obj = {
  name: "obj",
  foo: function foo() {
    return this.name;
  }
};

obj.foo();
```

上面解决了 this，下面来看下怎么实现参数的传递，call 方法可以传递任意参数列表，我们可以通过`arguments`来获取，它是一个类数组。

```js
function getName() {
  console.log(arguments); //Arguments(5) [1, 2, 3, 4, 5]
}
function foo() {
  var args = [];
  for (var i = 0; i < arguments.length; i++) {
    args.push("arguments[" + i + "]");
  }
  eval("getName(" + args + ")");
}
foo(1, 2, 3, 4, 5);
```

OK，这两块已经搞定了，下面就是实现

### call

```js
Function.prototype.calls = function(con) {
  con.fn = this;
  // 获取参数
  var args = [];
  for (var i = 1; i < arguments.length; i++) {
    args.push("arguments[" + i + "]");
  }
  var result = eval("con.fn(" + args + ")");
  delete con.fn;
  return result;
};
```

上面删除属性是为了避免污染，这里的`fn`可以是任意属性名只要保证不重复就行了，不过仔细观察上面函数还是有问题

1. call 的 this 可以是 `null` 或者 `undefined`；
2. 可以是字符串数字之类的，会转化为包装对象；

```js
Function.prototype.calls = function(con) {
  if (con == null) {
    con = typeof window === "object" ? window : global;
  }
  con = Object(con);
  con.fn = this;
  // 获取参数
  var args = [];
  for (var i = 1; i < arguments.length; i++) {
    args.push("arguments[" + i + "]");
  }
  var result = eval("con.fn(" + args + ")");
  delete con.fn;
  return result;
};
```

测试一下

```js
function foo() {
  return this.length;
}
console.log(foo.calls("obj")); // 3
```

撒花，这样就实现了 call

### apply

与 call 十分类似，这里就直接贴代码了

```js
Function.prototype.applys = function(con, arr) {
  if (con == null) {
    con = typeof window === "object" ? window : global;
  }
  con = Object(con);
  con.fn = this;
  var result;
  if (typeof arr === "object" && arr.length) {
    var args = [];
    for (var i = 0; i < arr.length; i++) {
      args.push("arr[" + i + "]");
    }
    result = eval("con.fn(" + args + ")");
  } else {
    result = eval("con.fn()");
  }
  delete con.fn;
  return result;
};
```

