### 非固定

非固定需要考虑的更多则是性能的问题，下面先贴一个完整的代码，在需要说明部分已经注释了

```html
<template>
  <div>
    <div class="root" ref="root" @scroll="scroll">
      <div class="container" :style="{ height: totalHeight }"></div>
      <ul class="content" :style="{ transform: getTransform }">
        <li
          class="item"
          v-for="item of nowList"
          :style="{
            height: item.height + 'px',
            lineHeight: item.height + 'px'
          }"
          :key="item.value"
        >
          {{ item.value }}
        </li>
      </ul>
    </div>
  </div>
</template>

<script>
  export default {
    data() {
      return {
        list: Array(10000)
          .fill(1)
          .map((f, i) => {
            return {
              value: i,
              height: this.getRandom(10, 100)
            };
          }),
        start: 0,
        end: 0,
        // 指针
        pointer: -1,
        // 缓存
        cache: {},
        // 初始总数
        initialHeight: 50
      };
    },
    computed: {
      totalHeight() {
        // 这里是获取总体高度，判断了两种情况，第一种是给定初始总数，另外一种则是没有，如果没有的话，高度就是已缓存的 + 未缓存的部分
        if (this.initialtotal >= 0) {
          const { top, height } =
            this.pointer >= 0
              ? this.getIndexOffset(this.pointer)
              : { top: 0, height: 0 };
          return `${top +
            height +
            (this.list.length - 1 - this.pointer) * this.initialHeight}px`;
        }
        const { height } = this.list.reduce(function(x, y) {
          return {
            height: x.height + y.height
          };
        });
        return height + "px";
      },
      // 可视数据
      nowList() {
        return this.list.slice(
          this.start,
          Math.min(this.end + 1, this.list.length)
        );
      },
      getTransform() {
        return `translate3d(0,${this.getIndexOffset(this.start).top}px,0)`;
      }
    },
    mounted() {
      this.scroll();
    },
    methods: {
      // 滚动事件
      scroll() {
        const dom = this.$refs.root;
        // 获取索引
        const start = this.getIndex(dom.scrollTop);
        // 把当前可视的高度 + 滚动条的高度，再去取索引
        const end = this.getIndex(dom.scrollTop + dom.clientHeight);
        this.start = start;
        this.end = end;
      },
      // 取出指定范围随机数
      getRandom(min, max) {
        return Math.floor(Math.random() * (max - min + 1)) + min;
      },
      // 根据滚动条y获取指定坐标
      getIndex(scrollTop) {
        // 判断思路很简单，如果高度大于滚动条肯定就出现了，另外一种则是判断了边界问题
        let total = 0;
        for (let i = 0, j = this.list.length; i < j; i++) {
          if (total >= scrollTop || j - 1 === i) {
            return i;
          }
          // 这里主要是起缓存作用的
          total += this.getIndexOffset(i).height;
        }
        return 0;
      },
      // 获取指定坐标的位置和高度
      getIndexOffset(index) {
        // 如果存在缓存中直接返回
        if (this.pointer >= index) {
          return this.cache[index];
        }
        let total = 0;
        // 这里是为了比较没有取到的情况
        if (this.pointer >= 0) {
          const li = this.cache[this.pointer];
          total = li.top + li.height;
        }
        // 注意上面因为取的值是li.top + li.height，所以i从 + 1开始
        for (let i = this.pointer + 1; i <= index; i++) {
          const size = this.list[i].height;
          this.cache[i] = {
            top: total,
            height: size
          };
          total += size;
        }
        if (index > this.pointer) {
          this.pointer = index;
        }

        return this.cache[index];
      }
    }
  };
</script>

<style lang="less" scoped>
  .root {
    border: 1px solid #999;
    list-style: none;
    overflow: auto;
    height: 400px;
    position: relative;
    .container {
      position: absolute;
      left: 0;
      top: 0;
      right: 0;
      z-index: -1;
    }
    .content {
      .container();
      z-index: 1;
      margin: 0;
      padding: 0;
      list-style: none;
    }
    .item {
      border-bottom: 1px solid #ccc;
      padding-left: 40px;
    }
  }
</style>
```

上面只最终的实现，实际上跟固定高度相比就是增加了获取索引的方法，固定高度我们是知道对应子项的高度，所以可以通过可视高度来计算，而这里我用了随机数来设置高度，所以需要获取到对应的索引。
上面代码同时也做了两点优化，一是缓存，二是总高度优化

总高度的实现有两种思路：

1. 计算所有的高度，这种实际上有点浪费性能；
2. 给定一个大概的值，拿缓存的值 + 没有缓存的值，没有缓存的值就是对应数据的长度 - 已缓存的坐标，之后每次缓存变化的时候再计算；

缓存则比较简单了，每次计算的时候把指针移动到计算的位置，同时将值添加上

## 参考文章

1. https://zhuanlan.zhihu.com/p/34585166

> 迭代器在很多语言都很常见，js 的 forEach 就是一个迭代器，下面就来介绍实现一个支持数组、对象、类数组的的 each 函数。

## 前言

写之前先整理一下思路

1. 我们首先需要判断是不是类数组，如果是数组和类数组就使用 for 循环，如果是对象我们就用 for...in 循环。
2. 回调函数的 this 处理，返回 false 终止循环

## 判断类型

判断基本类型我们可以使用 `typeof`，不过对于引用类型，比如数组和函数都会返回`object`，那么还有更好的判断方法么？
那就是`Object.prototype.toString`

```js
Object.prototype.toString.call({}); // "[object Object]"
Object.prototype.toString.call([]); // "[object Array]"
```

这里使用`Object.prototype.toString`的原因是一些引用类型的`toString`有自己的实现方式，比如数组的 `toString` 返回的就是以`","`分隔的文本。
数组的判断可以基于上面方法，下面就是封装成一个函数

```js
function isArray(arr) {
  return Object.prototype.toString.call(arr) === "[object Array]";
}
```

下面就来实现判断类数组的的思路，类数组就是指类似于

```js
{1: 123, 2：45, 6: 789, length: 7}
// or
// nodelist[]
// arguments
// ...
```

上面列举的几种对象，都存在`length`，而且都是一个对象，所以我们以这个为判断准则，下面就是实现

```js
function isClassArray(arr) {
  var length = !!arr && length in arr && arr.length;
  return (
    isArray(arr) ||
    length === 0 ||
    (typeof arr === "number" && length - 1 in arr)
  );
}
```

判断还是比较简洁的，判断了三种情况

1. 必须有 `length` 属性
2. `length` 为 0 的情况
3. `length- 1`必须存在

第一种就不说了，第二种为什么要判断 length 为 `0` 的情况呢？
假设有一个对象`{a: 1, b: 2, length: 0}`，认为它是类数组是不是不太合适，还有`arguments`是不是类数组对象根据函数的传递参数来变化，但是如果没有参数`length`为 0 就返回 false，是不是也不太合适，其实这里主要就是为了判断一些边界的对象

```js
function foo() {
  arguments.length; // 0
}
foo();
```

第三点，为什么要求 `length - 1` 存在？
数组的 length 永远是成员数+1，要求`length - 1` 存在实际上这是为了数组和类数组的形式想对应，例如：

```js
var a = [, , 2]; // length: 3
// 对应类数组
var obj = {
  2: 2,
  length: 3
};
```

上面数组存在`,`我们认为前面两位就是空，但是如果取消了`length - 1`必须存在，那么下面这种写法会出现下面情况

```js
// length: 2
var a = [1, ,];
var obj = {
  0: 1，
  length: 1
};
```

## each

上面把所需要用的讲解完毕了，下面就来实现一个最终版的 each

```js
function isArray(arr) {
  return Object.prototype.toString.call(arr) === "[object Array]";
}
function isClassArray(arr) {
  var length = !!arr && length in arr && arr.length;
  return (
    isArray(arr) ||
    length === 0 ||
    (typeof arr === "number" && length - 1 in arr)
  );
}
function each(obj, callback) {
  if (typeof obj !== "object") {
    return obj;
  }
  // 数组和类数组
  if (isClassArray(obj)) {
    for (let i = 0; i < obj.length; i++) {
      let v = callback.call(obj, i, obj[i]);
      if (v === false) {
        break;
      }
    }
  } else {
    for (let item in obj) {
      let v = callback.call(obj, item, obj[item]);
      if (v === false) {
        break;
      }
    }
  }
}
```

