本来打算从零写一个，不过意外看到一篇好文，下面就根据他的思路来实现一个节流，[JavaScript专题之跟着 underscore 学节流 ](https://github.com/mqyqingfeng/Blog/issues/26)

## 前言
节流有两种实现，第一种使用定时器，另外一种则是根据时间戳，判断两次执行的时间间隔，下面简单些一下这两种的实现。
- 定时器
``` js
function throttle(fn, time) {
  let timing = null;
  return function(...rest) {
    if(!timing) {
      timing = setTimeout(() => {
        timing = null;
        fn.apply(this, rest);
      }, time);
    }
  };
};
```
- 时间戳
``` js
function throttle (fn, time) {
  let times = 0;
  return function (...rest) {
    const s = time - (new Date().getTime() - times)
    if (s <= 0) {
      times = new Date().getTime();
      fn.apply(this, rest);
    }
  };
};
```
下面就是将两者结合起来

## 节流
``` js
// 节流
// initial初始立即执行，front最后执行一次
function throttle (fn, time, { initial = true, front = false } = {}) {
  // 上一次执行时间
  let times = 0;
  // 定时器
  let timing = null;
  function next (...args) {
    // 判断条件，如果不是初始执行，改用定时器方法执行
    if (!initial && !times) {
      times = new Date().getTime();
    }
    const now = time - (new Date().getTime() - times);
    // now > time是判断更改系统时间的边界问题，now正常情况下，肯定小于time
    if (now <= 0 || now > time) {
      if (!timing) {
        clearTimeout(timing);
        timing = null;
      }
      times = new Date().getTime();
      fn.apply(this, args);
      // 清理一下内存
      if (!timing) {
        args = null;
      }
    } else if (!timing && front) {
      timing = setTimeout(() => {
        timing = null;
        times = initial ? 0 : new Date().getTime();
        fn.apply(this, args);
        if (!timing) {
          args = null;
        }
      }, time);
    }
  }
  // 取消
  next.cancel = function () {
    clearTimeout(timing);
    timing = null;
    // 为0即可，上面有初始判断条件
    times = 0;
  };
  return next;
};
```
## 注意
上面有两个参数，但是不能同时设置为false

## 前言

1. 为什么需要使用防抖函数
   当一个事件触发太多的时候会出现性能问题，比如`mousemove`、`resize`、`scroll`等，看一个没有任何防抖的`mousemove`事件

![1](https://cdn.xiaowo.live/62198507-526ef780-b3b4-11e9-8019-21e510329930_a99f4081.gif)

2. 什么是防抖?
   简单就是你任意触发我只执行最后一次操作

根据上面的定义可以很轻松编写出一个简单的防抖函数

### 实现

```js
// 第一版
function antiShake(call, time) {
  var i = null;
  return function() {
    clearTimeout(i);
    i = setTimeout(call, time);
  };
}
```

![2](https://cdn.xiaowo.live/62198572-77fc0100-b3b4-11e9-8ad5-a46ac6a5a2e1_b9ad8f6f.gif)

### this 以及参数

不过这样有一个问题，就是 this 指向不正确以及参数丢失，这里以`mousemove`为例，触发函数的时候会有一个`MouseEvent`对象，如果打印函数参数会发现为`undefined`，下面就来修复一下

```js
//  第二版
function antiShake(call, time) {
  var i = null;
  return function() {
    var that = this;
    var rest = arguments;
    clearTimeout(i);
    i = setTimeout(function() {
      call.apply(that, rest);
    }, time);
  };
}
```

### 立即执行

有时候我不想让他等待时间结束在执行，而是一开始就触发
![4](https://cdn.xiaowo.live/62198651-99f58380-b3b4-11e9-9fbc-78e805b13910_2232560a.gif)

```js
// 第三版
function antiShake(call, time, immediately) {
  var i = null;
  return function() {
    var that = this;
    var rest = arguments;
    clearTimeout(i);
    if (immediately) {
      var reversal = !i;
      i = setTimeout(function() {
        i = null;
      }, time);

      if (reversal) {
        call.apply(that, rest);
      }
    } else {
      i = setTimeout(function() {
        call.apply(that, rest);
      }, time);
    }
  };
}
```

### 返回值

异步执行的函数我们没办法同步返回他的值，但是对于立即执行的函数，我们应当把值返回

```js
// 第四版
function antiShake(call, time, immediately) {
  var i = null;
  return function() {
    var that = this;
    var rest = arguments;
    clearTimeout(i);
    if (immediately) {
      var reversal = !i;
      i = setTimeout(function() {
        i = null;
      }, time);

      if (reversal) {
        return call.apply(that, rest);
      }
    } else {
      i = setTimeout(function() {
        call.apply(that, rest);
      }, time);
    }
  };
}
```

### 取消

到这里基本上防抖函数就基本写完了，上述我们用`mousemove`事件举例，但是我想当鼠标移开的时候我想取消这个事件，这也是正常的需求，下面就来实现取消功能

```js
function antiShake(call, time, immediately) {
  var i = null;
  function _private() {
    var that = this;
    var rest = arguments;
    clearTimeout(i);
    if (immediately) {
      var reversal = !i;
      i = setTimeout(function() {
        i = null;
      }, time);

      if (reversal) {
        return call.apply(that, rest);
      }
    } else {
      i = setTimeout(function() {
        call.apply(that, rest);
      }, time);
    }
  }
  _private.cancel = function() {
    clearTimeout(i);
    i = null;
  };
  return _private;
}
```

